1: /**
2:  *  Copyright (c) 2019 by Contributors
3:  * @file shared_mem.cc
4:  * @brief Shared memory management.
5:  */
6: #ifndef _WIN32
7: #include <fcntl.h>
8: #include <sys/mman.h>
9: #include <unistd.h>
10: #endif
11: #include <dgl/runtime/shared_mem.h>
12: #include <dmlc/logging.h>
13: #include <stdio.h>
14: #include <string.h>
15: 
16: #include "resource_manager.h"
17: 
18: namespace dgl {
19: namespace runtime {
20: 
21: /**
22:  * Shared memory is a resource that cannot be cleaned up if the process doesn't
23:  * exit normally. We'll manage the resource with ResourceManager.
24:  */
25: class SharedMemoryResource : public Resource {
26:   std::string name;
27: 
28:  public:
29:   explicit SharedMemoryResource(const std::string &name) { this->name = name; }
30: 
31:   void Destroy() {
32:     // LOG(INFO) << "remove " << name << " for shared memory";
33: #ifndef _WIN32
34:     shm_unlink(name.c_str());
35: #else  // _WIN32
36:     // NOTHING; Windows automatically removes the shared memory object once all
37:     // handles are unmapped.
38: #endif
39:   }
40: };
41: 
42: SharedMemory::SharedMemory(const std::string &name) {
43:   this->name = name;
44:   this->own_ = false;
45: #ifndef _WIN32
46:   this->fd_ = -1;
47: #else
48:   this->handle_ = nullptr;
49: #endif
50:   this->ptr_ = nullptr;
51:   this->size_ = 0;
52: }
53: 
54: SharedMemory::~SharedMemory() {
55: #ifndef _WIN32
56:   if (ptr_ && size_ != 0) CHECK(munmap(ptr_, size_) != -1) << strerror(errno);
57:   if (fd_ != -1) close(fd_);
58:   if (own_) {
59:     // LOG(INFO) << "remove " << name << " for shared memory";
60:     if (name != "") {
61:       shm_unlink(name.c_str());
62:       // The resource has been deleted. We don't need to keep track of it any
63:       // more.
64:       DeleteResource(name);
65:     }
66:   }
67: #else
68:   if (ptr_) CHECK(UnmapViewOfFile(ptr_)) << "Win32 Error: " << GetLastError();
69:   if (handle_) CloseHandle(handle_);
70:     // Windows do not need a separate shm_unlink step.
71: #endif  // _WIN32
72: }
73: 
74: void *SharedMemory::CreateNew(size_t sz) {
75: #ifndef _WIN32
76:   this->own_ = true;
77: 
78:   // We need to create a shared-memory file.
79:   // TODO(zhengda) we need to report error if the shared-memory file exists.
80:   int flag = O_RDWR | O_CREAT;
81:   fd_ = shm_open(name.c_str(), flag, S_IRUSR | S_IWUSR);
82:   CHECK_NE(fd_, -1) << "fail to open " << name << ": " << strerror(errno);
83:   // Shared memory cannot be deleted if the process exits abnormally in Linux.
84:   AddResource(name, std::shared_ptr<Resource>(new SharedMemoryResource(name)));
85:   auto res = ftruncate(fd_, sz);
86:   CHECK_NE(res, -1) << "Failed to truncate the file. " << strerror(errno);
87:   ptr_ = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_SHARED, fd_, 0);
88:   CHECK_NE(ptr_, MAP_FAILED)
89:       << "Failed to map shared memory. mmap failed with error "
90:       << strerror(errno);
91:   this->size_ = sz;
92:   return ptr_;
93: #else
94:   handle_ = CreateFileMapping(
95:       INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE,
96:       static_cast<DWORD>(sz >> 32), static_cast<DWORD>(sz & 0xFFFFFFFF),
97:       name.c_str());
98:   CHECK(handle_ != nullptr)
99:       << "fail to open " << name << ", Win32 error: " << GetLastError();
100:   ptr_ = MapViewOfFile(handle_, FILE_MAP_ALL_ACCESS, 0, 0, sz);
101:   if (ptr_ == nullptr) {
102:     LOG(FATAL) << "Memory mapping failed, Win32 error: " << GetLastError();
103:     CloseHandle(handle_);
104:     return nullptr;
105:   }
106:   this->size_ = sz;
107:   return ptr_;
108: #endif  // _WIN32
109: }
110: 
111: void *SharedMemory::Open(size_t sz) {
112: #ifndef _WIN32
113:   int flag = O_RDWR;
114:   fd_ = shm_open(name.c_str(), flag, S_IRUSR | S_IWUSR);
115:   CHECK_NE(fd_, -1) << "fail to open " << name << ": " << strerror(errno);
116:   ptr_ = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_SHARED, fd_, 0);
117:   CHECK_NE(ptr_, MAP_FAILED)
118:       << "Failed to map shared memory. mmap failed with error "
119:       << strerror(errno);
120:   this->size_ = sz;
121:   return ptr_;
122: #else
123:   handle_ = OpenFileMapping(FILE_MAP_ALL_ACCESS, FALSE, name.c_str());
124:   CHECK(handle_ != nullptr)
125:       << "fail to open " << name << ", Win32 Error: " << GetLastError();
126:   ptr_ = MapViewOfFile(handle_, FILE_MAP_ALL_ACCESS, 0, 0, sz);
127:   if (ptr_ == nullptr) {
128:     LOG(FATAL) << "Memory mapping failed, Win32 error: " << GetLastError();
129:     CloseHandle(handle_);
130:     return nullptr;
131:   }
132:   this->size_ = sz;
133:   return ptr_;
134: #endif  // _WIN32
135: }
136: 
137: bool SharedMemory::Exist(const std::string &name) {
138: #ifndef _WIN32
139:   int fd = shm_open(name.c_str(), O_RDONLY, S_IRUSR | S_IWUSR);
140:   if (fd >= 0) {
141:     close(fd);
142:     return true;
143:   } else {
144:     return false;
145:   }
146: #else
147:   HANDLE handle = OpenFileMapping(FILE_MAP_ALL_ACCESS, FALSE, name.c_str());
148:   if (handle != nullptr) {
149:     CloseHandle(handle);
150:     return true;
151:   } else {
152:     return false;
153:   }
154: #endif  // _WIN32
155: }
156: 
157: }  // namespace runtime
158: }  // namespace dgl

