21: // Module to load from dynamic shared libary.
22: // This is the default module DGL used for host-side AOT
23: class DSOModuleNode final : public ModuleNode {
24:  public:
25:   ~DSOModuleNode() {
26:     if (lib_handle_) Unload();
27:   }
28: 
29:   const char* type_key() const final { return "dso"; }
30: 
31:   PackedFunc GetFunction(
32:       const std::string& name,
33:       const std::shared_ptr<ModuleNode>& sptr_to_self) final {
34:     BackendPackedCFunc faddr;
35:     if (name == runtime::symbol::dgl_module_main) {
36:       const char* entry_name = reinterpret_cast<const char*>(
37:           GetSymbol(runtime::symbol::dgl_module_main));
38:       CHECK(entry_name != nullptr)
39:           << "Symbol " << runtime::symbol::dgl_module_main
40:           << " is not presented";
41:       faddr = reinterpret_cast<BackendPackedCFunc>(GetSymbol(entry_name));
42:     } else {
43:       faddr = reinterpret_cast<BackendPackedCFunc>(GetSymbol(name.c_str()));
44:     }
45:     if (faddr == nullptr) return PackedFunc();
46:     return WrapPackedFunc(faddr, sptr_to_self);
47:   }
48: 
49:   void Init(const std::string& name) {
50:     Load(name);
51:     if (auto* ctx_addr = reinterpret_cast<void**>(
52:             GetSymbol(runtime::symbol::dgl_module_ctx))) {
53:       *ctx_addr = this;
54:     }
55:     InitContextFunctions(
56:         [this](const char* fname) { return GetSymbol(fname); });
57:     // Load the imported modules
58:     const char* dev_mblob = reinterpret_cast<const char*>(
59:         GetSymbol(runtime::symbol::dgl_dev_mblob));
60:     if (dev_mblob != nullptr) {
61:       ImportModuleBlob(dev_mblob, &imports_);
62:     }
63:   }
64: 
65:  private:
66:   // Platform dependent handling.
67: #if defined(_WIN32)
68:   // library handle
69:   HMODULE lib_handle_{nullptr};
70:   // Load the library
71:   void Load(const std::string& name) {
72:     // use wstring version that is needed by LLVM.
73:     std::wstring wname(name.begin(), name.end());
74:     lib_handle_ = LoadLibraryW(wname.c_str());
75:     CHECK(lib_handle_ != nullptr)
76:         << "Failed to load dynamic shared library " << name;
77:   }
78:   void* GetSymbol(const char* name) {
79:     return reinterpret_cast<void*>(
80:         GetProcAddress(lib_handle_, (LPCSTR)name));  // NOLINT(*)
81:   }
82:   void Unload() { FreeLibrary(lib_handle_); }
83: #else
84:   // Library handle
85:   void* lib_handle_{nullptr};
86:   // load the library
87:   void Load(const std::string& name) {
88:     lib_handle_ = dlopen(name.c_str(), RTLD_LAZY | RTLD_LOCAL);
89:     CHECK(lib_handle_ != nullptr)
90:         << "Failed to load dynamic shared library " << name << " " << dlerror();
91:   }
92:   void* GetSymbol(const char* name) { return dlsym(lib_handle_, name); }
93:   void Unload() { dlclose(lib_handle_); }
94: #endif
95: };
96: 
97: DGL_REGISTER_GLOBAL("module.loadfile_so")
98:     .set_body([](DGLArgs args, DGLRetValue* rv) {
99:       std::shared_ptr<DSOModuleNode> n = std::make_shared<DSOModuleNode>();
100:       n->Init(args[0]);
101:       *rv = runtime::Module(n);
102:     });
103: }  // namespace runtime
104: }  // namespace dgl

