3:  * @file socket_pool.cc
4:  * @brief Socket pool of nonblocking sockets for DGL distributed training.
5:  */
6: #include "socket_pool.h"
7: 
8: #include <dmlc/logging.h>
9: 
10: #include "tcp_socket.h"
11: 
12: #ifdef USE_EPOLL
13: #include <sys/epoll.h>
14: #endif
15: 
16: namespace dgl {
17: namespace network {
18: 
19: SocketPool::SocketPool() {
20: #ifdef USE_EPOLL
21:   epfd_ = epoll_create1(0);
22:   if (epfd_ < 0) {
23:     LOG(FATAL) << "SocketPool cannot create epfd";
24:   }
25: #endif
26: }
27: 
28: void SocketPool::AddSocket(
29:     std::shared_ptr<TCPSocket> socket, int socket_id, int events) {
30:   int fd = socket->Socket();
31:   tcp_sockets_[fd] = socket;
32:   socket_ids_[fd] = socket_id;
33: 
34: #ifdef USE_EPOLL
35:   epoll_event e;
36:   e.data.fd = fd;
37:   if (events == READ) {
38:     e.events = EPOLLIN;
39:   } else if (events == WRITE) {
40:     e.events = EPOLLOUT;
41:   } else if (events == READ + WRITE) {
42:     e.events = EPOLLIN | EPOLLOUT;
43:   }
44:   if (epoll_ctl(epfd_, EPOLL_CTL_ADD, fd, &e) < 0) {
45:     LOG(FATAL) << "SocketPool cannot add socket";
46:   }
47:   socket->SetNonBlocking(true);
48: #else
49:   if (tcp_sockets_.size() > 1) {
50:     LOG(FATAL) << "SocketPool supports only one socket if not use epoll."
51:                   "Please turn on USE_EPOLL on building";
52:   }
53: #endif
54: }
55: 
56: size_t SocketPool::RemoveSocket(std::shared_ptr<TCPSocket> socket) {
57:   int fd = socket->Socket();
58:   socket_ids_.erase(fd);
59:   tcp_sockets_.erase(fd);
60: #ifdef USE_EPOLL
61:   epoll_ctl(epfd_, EPOLL_CTL_DEL, fd, NULL);
62: #endif
63:   return socket_ids_.size();
64: }
65: 
66: SocketPool::~SocketPool() {
67: #ifdef USE_EPOLL
68:   for (auto& id : socket_ids_) {
69:     int fd = id.first;
70:     epoll_ctl(epfd_, EPOLL_CTL_DEL, fd, NULL);
71:   }
72: #endif
73: }
74: 
75: std::shared_ptr<TCPSocket> SocketPool::GetActiveSocket(int* socket_id) {
76:   if (socket_ids_.empty()) {
77:     return nullptr;
78:   }
79: 
80:   for (;;) {
81:     while (pending_fds_.empty()) {
82:       Wait();
83:     }
84:     int fd = pending_fds_.front();
85:     pending_fds_.pop();
86: 
87:     // Check if this socket is not removed
88:     if (socket_ids_.find(fd) != socket_ids_.end()) {
89:       *socket_id = socket_ids_[fd];
90:       return tcp_sockets_[fd];
91:     }
92:   }
93: 
94:   return nullptr;
95: }
96: 
97: void SocketPool::Wait() {
98: #ifdef USE_EPOLL
99:   static const int MAX_EVENTS = 10;
100:   epoll_event events[MAX_EVENTS];
101:   int nfd = epoll_wait(epfd_, events, MAX_EVENTS, -1 /*Timeout*/);
102:   for (int i = 0; i < nfd; ++i) {
103:     pending_fds_.push(events[i].data.fd);
104:   }
105: #else
106:   pending_fds_.push(tcp_sockets_.begin()->second->Socket());
107: #endif
108: }
109: 
110: }  // namespace network
111: }  // namespace dgl

