3:  * @file tcp_socket.cc
4:  * @brief TCP socket for DGL distributed training.
5:  */
6: #include "tcp_socket.h"
7: 
8: #include <dmlc/logging.h>
9: 
10: #ifndef _WIN32
11: #include <arpa/inet.h>
12: #include <fcntl.h>
13: #include <netdb.h>
14: #include <netinet/in.h>
15: #include <sys/socket.h>
16: #include <unistd.h>
17: #endif  // !_WIN32
18: #include <errno.h>
19: #include <string.h>
20: 
21: namespace dgl {
22: namespace network {
23: 
24: typedef struct sockaddr_in SAI;
25: typedef struct sockaddr SA;
26: 
27: TCPSocket::TCPSocket() {
28:   // init socket
29:   socket_ = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
30:   if (socket_ < 0) {
31:     LOG(FATAL) << "Can't create new socket. Error: " << strerror(errno);
32:   }
33: #ifndef _WIN32
34:   // This is to make sure the same port can be reused right after the socket is
35:   // closed.
36:   int enable = 1;
37:   if (setsockopt(socket_, SOL_SOCKET, SO_REUSEADDR, &enable, sizeof(int)) < 0) {
38:     LOG(WARNING) << "cannot make the socket reusable. Error: "
39:                  << strerror(errno);
40:   }
41: #endif  // _WIN32
42: }
43: 
44: TCPSocket::~TCPSocket() { Close(); }
45: 
46: bool TCPSocket::Connect(const char *ip, int port) {
47:   SAI sa_server;
48:   sa_server.sin_family = AF_INET;
49:   sa_server.sin_port = htons(port);
50: 
51:   int retval = 0;
52:   do {  // retry if EINTR failure appears
53:     if (0 < inet_pton(AF_INET, ip, &sa_server.sin_addr) &&
54:         0 <= (retval = connect(
55:                   socket_, reinterpret_cast<SA *>(&sa_server),
56:                   sizeof(sa_server)))) {
57:       return true;
58:     }
59:   } while (retval == -1 && errno == EINTR);
60: 
61:   return false;
62: }
63: 
64: bool TCPSocket::Bind(const char *ip, int port) {
65:   SAI sa_server;
66:   sa_server.sin_family = AF_INET;
67:   sa_server.sin_port = htons(port);
68:   int ret = 0;
69:   ret = inet_pton(AF_INET, ip, &sa_server.sin_addr);
70:   if (ret == 0) {
71:     LOG(ERROR) << "Invalid IP: " << ip;
72:     return false;
73:   } else if (ret < 0) {
74:     LOG(ERROR) << "Failed to convert [" << ip
75:                << "] to binary form, error: " << strerror(errno);
76:     return false;
77:   }
78:   do {  // retry if EINTR failure appears
79:     if (0 <=
80:         (ret = bind(
81:              socket_, reinterpret_cast<SA *>(&sa_server), sizeof(sa_server)))) {
82:       return true;
83:     }
84:   } while (ret == -1 && errno == EINTR);
85: 
86:   LOG(ERROR) << "Failed bind on " << ip << ":" << port
87:              << " , error: " << strerror(errno);
88:   return false;
89: }
90: 
91: bool TCPSocket::Listen(int max_connection) {
92:   int retval;
93:   do {  // retry if EINTR failure appears
94:     if (0 <= (retval = listen(socket_, max_connection))) {
95:       return true;
96:     }
97:   } while (retval == -1 && errno == EINTR);
98: 
99:   LOG(ERROR) << "Failed listen on socket fd: " << socket_
100:              << " , error: " << strerror(errno);
101:   return false;
102: }
103: 
104: bool TCPSocket::Accept(TCPSocket *socket, std::string *ip, int *port) {
105:   int sock_client;
106:   SAI sa_client;
107:   socklen_t len = sizeof(sa_client);
108: 
109:   do {  // retry if EINTR failure appears
110:     sock_client = accept(socket_, reinterpret_cast<SA *>(&sa_client), &len);
111:   } while (sock_client == -1 && errno == EINTR);
112: 
113:   if (sock_client < 0) {
114:     LOG(ERROR) << "Failed accept connection on " << *ip << ":" << *port
115:                << ", error: " << strerror(errno)
116:                << (errno == EAGAIN ? " SO_RCVTIMEO timeout reached" : "");
117:     return false;
118:   }
119: 
120:   char tmp[INET_ADDRSTRLEN];
121:   const char *ip_client =
122:       inet_ntop(AF_INET, &sa_client.sin_addr, tmp, sizeof(tmp));
123:   CHECK(ip_client != nullptr);
124:   ip->assign(ip_client);
125:   *port = ntohs(sa_client.sin_port);
126:   socket->socket_ = sock_client;
127: 
128:   return true;
129: }
