131: #ifdef _WIN32
132: bool TCPSocket::SetNonBlocking(bool flag) {
133:   int result;
134:   u_long argp = flag ? 1 : 0;
135: 
136:   // XXX Non-blocking Windows Sockets apparently has tons of issues:
137:   // http://www.sockets.com/winsock.htm#Overview_BlockingNonBlocking
138:   // Since SetBlocking() is not used at all, I'm leaving a default
139:   // implementation here.  But be warned that this is not fully tested.
140:   if ((result = ioctlsocket(socket_, FIONBIO, &argp)) != NO_ERROR) {
141:     LOG(ERROR) << "Failed to set socket status.";
142:     return false;
143:   }
144:   return true;
145: }
146: #else   // !_WIN32
147: bool TCPSocket::SetNonBlocking(bool flag) {
148:   int opts;
149: 
150:   if ((opts = fcntl(socket_, F_GETFL)) < 0) {
151:     LOG(ERROR) << "Failed to get socket status.";
152:     return false;
153:   }
154: 
155:   if (flag) {
156:     opts |= O_NONBLOCK;
157:   } else {
158:     opts &= ~O_NONBLOCK;
159:   }
160: 
161:   if (fcntl(socket_, F_SETFL, opts) < 0) {
162:     LOG(ERROR) << "Failed to set socket status.";
163:     return false;
164:   }
165: 
166:   return true;
167: }
168: #endif  // _WIN32
