170: void TCPSocket::SetTimeout(int timeout) {
171: #ifdef _WIN32
172:   timeout = timeout * 1000;  // WIN API accepts millsec
173:   setsockopt(
174:       socket_, SOL_SOCKET, SO_RCVTIMEO, reinterpret_cast<char *>(&timeout),
175:       sizeof(timeout));
176: #else   // !_WIN32
177:   struct timeval tv;
178:   tv.tv_sec = timeout;
179:   tv.tv_usec = 0;
180:   setsockopt(socket_, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
181: #endif  // _WIN32
182: }
