187:   if (socket_ >= 0) {
188: #ifdef _WIN32
189:     CHECK_EQ(0, closesocket(socket_));
190: #else   // !_WIN32
191:     CHECK_EQ(0, close(socket_));
192: #endif  // _WIN32
193:     socket_ = -1;
194:   }
