23: class ThreadGroup::Impl {
24:  public:
25:   Impl(
26:       int num_workers, std::function<void(int)> worker_callback,
27:       bool exclude_worker0)
28:       : num_workers_(num_workers) {
29:     CHECK_GE(num_workers, 1)
30:         << "Requested a non-positive number of worker threads.";
31:     for (int i = exclude_worker0; i < num_workers_; ++i) {
32:       threads_.emplace_back([worker_callback, i] { worker_callback(i); });
33:     }
34:     InitSortedOrder();
35:   }
36:   ~Impl() { Join(); }
37: 
38:   void Join() {
39:     for (auto &t : threads_) {
40:       if (t.joinable()) t.join();
41:     }
42:   }
43: 
44:   int Configure(AffinityMode mode, int nthreads, bool exclude_worker0) {
45:     int num_workers_used = 0;
46:     if (mode == kLittle) {
47:       num_workers_used = little_count_;
48:     } else if (mode == kBig) {
49:       num_workers_used = big_count_;
50:     } else {
51:       // use default
52:       num_workers_used = threading::MaxConcurrency();
53:     }
54:     // if a specific number was given, use that
55:     if (nthreads) {
56:       num_workers_used = nthreads;
57:     }
58:     // if MaxConcurrency restricted the number of workers (e.g., due to
59:     // hyperthreading), respect the restriction. On CPUs with N logical cores
60:     // and N/2 physical cores this will set affinity to the first N/2 logical
61:     // ones.
62:     num_workers_used = std::min(num_workers_, num_workers_used);
63: 
64:     const char *val = getenv("DGL_BIND_THREADS");
65:     if (val == nullptr || atoi(val) == 1) {
66:       // Do not set affinity if there are more workers than found cores
67:       if (sorted_order_.size() >= static_cast<unsigned int>(num_workers_)) {
68:         SetAffinity(exclude_worker0, mode == kLittle);
69:       } else {
70:         LOG(WARNING)
71:             << "The thread affinity cannot be set when the number of workers"
72:             << "is larger than the number of available cores in the system.";
73:       }
74:     }
75:     return num_workers_used;
76:   }
77: 
78:  private:
79:   // bind worker threads to disjoint cores
80:   // if worker 0 is offloaded to master, i.e. exclude_worker0 is true,
81:   // the master thread is bound to core 0.
82:   void SetAffinity(bool exclude_worker0, bool reverse = false) {
83: #if defined(__ANDROID__)
84: #ifndef CPU_SET
85: #define CPU_SETSIZE 1024
86: #define __NCPUBITS (8 * sizeof(uint64_t))
87:     typedef struct {
88:       uint64_t __bits[CPU_SETSIZE / __NCPUBITS];
89:     } cpu_set_t;
90: 
91: #define CPU_SET(cpu, cpusetp) \
92:   ((cpusetp)->__bits[(cpu) / __NCPUBITS] |= (1UL << ((cpu) % __NCPUBITS)))
93: #define CPU_ZERO(cpusetp) memset((cpusetp), 0, sizeof(cpu_set_t))
94: #endif
95: #endif
96: #if defined(__linux__) || defined(__ANDROID__)
97:     CHECK_GE(sorted_order_.size(), num_workers_);
98: 
99:     for (unsigned i = 0; i < threads_.size(); ++i) {
100:       unsigned core_id;
101:       if (reverse) {
102:         core_id =
103:             sorted_order_[sorted_order_.size() - (i + exclude_worker0) - 1];
104:       } else {
105:         core_id = sorted_order_[i + exclude_worker0];
106:       }
107:       cpu_set_t cpuset;
108:       CPU_ZERO(&cpuset);
109:       CPU_SET(core_id, &cpuset);
110: #if defined(__ANDROID__)
111:       sched_setaffinity(
112:           threads_[i].native_handle(), sizeof(cpu_set_t), &cpuset);
113: #else
114:       pthread_setaffinity_np(
115:           threads_[i].native_handle(), sizeof(cpu_set_t), &cpuset);
116: #endif
117:     }
118:     if (exclude_worker0) {  // bind the master thread to core 0
119:       cpu_set_t cpuset;
120:       CPU_ZERO(&cpuset);
121:       if (reverse) {
122:         CPU_SET(sorted_order_[sorted_order_.size() - 1], &cpuset);
123:       } else {
124:         CPU_SET(sorted_order_[0], &cpuset);
125:       }
126: #if defined(__ANDROID__)
127:       sched_setaffinity(pthread_self(), sizeof(cpu_set_t), &cpuset);
128: #else
129:       pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
130: #endif
131:     }
132: #endif
133:   }
